((select id from errors where code = '0x80070005'), (select id from error_contexts where slug = 'microsoft-store'), 'Reiniciar Microsoft Store', 'Tente reiniciar a Microsoft Store.', 'Feche e reabra a Microsoft Store.', 'low', 'easy', 'official', 'https://support.microsoft.com', 50, 'verified', 'published', now(), now()),
